import { View, Text, Pressable, StyleSheet } from "react-native";
import { createContext, useContext, useState } from "react";
import { registerRootComponent } from "expo";

const ThemeContext = createContext(null);

function Card() {
  const { dark } = useContext(ThemeContext);
  // энд бичнэ үү: dark-аас хамааруулж bg сонго
  const bg = "#ffffff";
  return <View nativeID="card" style={[styles.card, { backgroundColor: bg }]}><Text style={{ color: dark ? "#fff" : "#000" }}>Бараа</Text></View>;
}
function Toggle() {
  const { setDark } = useContext(ThemeContext);
  return <Pressable nativeID="toggle" style={styles.b} onPress={() => setDark((d) => !d)}><Text style={styles.t}>Тема</Text></Pressable>;
}

function App() {
  const [dark, setDark] = useState(false);
  return (
    <ThemeContext.Provider value={{ dark, setDark }}>
      <View style={styles.s}><Card /><Toggle /></View>
    </ThemeContext.Provider>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 20, padding: 24, alignItems: "center", justifyContent: "center" },
  card: { padding: 30, borderRadius: 16, borderWidth: 1, borderColor: "#cbd5e1" },
  b: { backgroundColor: "#2563eb", padding: 12, borderRadius: 10 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

